  background: var(--accent-ultra-light);
  color: var(--accent-dark);
}
.news-tag[data-type="Award"] {
  background: var(--accent);
  color: var(--white);
}

.prose .news-end {
  text-align: center;
  letter-spacing: 0.4em;
  color: var(--base-semi-dark);
}
.prose .news-dateline {
  font-family: var(--text-font-family), Arial, sans-serif;
  font-size: 0.8em;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.result-card {
  border-top: calc(var(--border-size) * 3) solid var(--accent);
}
.result-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--pc-shadow-m);
}

.areas-menu__summary {
  list-style: none;
}
.areas-menu__summary::-webkit-details-marker {
  display: none;
}
.areas-menu__summary .areas-menu__city-name {
  flex: 1;
  min-width: 0;
}
@media (max-width: 1279px) {
  .areas-menu__summary {
    cursor: pointer;
  }
}

.areas-menu__chevron {
  display: none;
}
@media (max-width: 1279px) {
  .areas-menu__chevron {
    display: inline-grid;
    place-items: center;
    flex: none;
    width: 4.4rem;
    height: 4.4rem;
    font-size: 1.8rem;
    color: var(--accent-dark);
    transition: transform 0.25s var(--pc-ease);
  }
}
@media (max-width: 1279px) {
  details[open] > .areas-menu__summary .areas-menu__chevron {
    transform: rotate(180deg);
  }
}

.firm-menu {
  box-shadow: var(--pc-shadow-l);
}
.firm-menu > li {
  display: grid;
  grid-template-columns: 30rem minmax(0, 1fr);
  gap: var(--space-xl);
  align-items: start;
  list-style: none;
}
@media (max-width: 1279px) {
  .firm-menu {
    padding: 0 0 var(--space-s);
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }
}
@media (max-width: 1279px) {
  .firm-menu > li {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-m);
  }
}
@media (min-width: 1280px) {
  .main-nav ul.firm-menu {
    padding: var(--space-l);
  }
}

.firm-menu__heading {
  font-family: var(--heading-font-family), "Libre Caslon Text", Georgia, serif;
}
@media (max-width: 1279px) {
  .firm-menu__heading {
    display: none;
  }
}

.firm-menu__link:hover {
  border-left-color: var(--accent);
}
@media (max-width: 1279px) {
  .firm-menu__link {
    margin-inline: 0;
    padding: calc(var(--space-xs) * 0.75) 0;
    border-left: 0;
  }
}
@media (max-width: 1279px) {
  .firm-menu__link:hover {
    background: none;
  }
}

@media (max-width: 1279px) {
  .firm-menu__team {
    padding-top: var(--space-s);
    border-top: var(--border-size) solid var(--base-trans-10);
  }
}

.firm-menu__team-title {
  font-family: var(--heading-font-family), "Libre Caslon Text", Georgia, serif;
}
@media (max-width: 1279px) {
  .firm-menu__team-title {
    font-size: var(--text-l);
  }
}

@media (max-width: 1279px) {
  .firm-menu__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-xs) var(--space-s);
  }
}
@media (max-width: 599px) {
  .firm-menu__grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

.firm-menu__card .team-photo {
  transition: transform 0.5s var(--pc-ease);
}
.firm-menu__card:hover .team-photo {
  transform: scale(1.04);
}
.firm-menu__card:hover .firm-menu__name {
  color: var(--accent-dark);
}
@media (max-width: 1279px) {
  .firm-menu__card {
    flex-direction: row;
    align-items: center;
    gap: var(--space-xs);
    padding: calc(var(--space-xs) * 0.5) 0;
  }
}

.firm-menu__photo {
  background: linear-gradient(170deg, var(--primary-light) 0%, var(--primary) 100%);
}
@media (max-width: 1279px) {
  .firm-menu__photo {
    flex: none;
    width: 5.6rem;
  }
}

.social-links {
  flex-wrap: wrap;
  list-style: none;
  padding: 0;
}
.social-links li {
  background: none;
  flex: 0 0 auto;
  width: auto;
}
.social-links li a {
  display: inline-grid;
  place-items: center;
  min-width: 4.4rem;
  min-height: 4.4rem;
  margin: calc(var(--space-xs) * -1);
  padding: var(--space-xs);
  transition: transform 0.2s var(--pc-ease), opacity 0.2s;
}
.social-links li a:hover {
  transform: translateY(-2px);
}
.social-links .icon {
  transition: color 0.2s;
}
.social-links.social-links {
  gap: var(--space-l);
}
